package com.company.skillplatform.audit.application;import com.company.skillplatform.audit.infrastructure.entity.DownloadLogEntity;import com.company.skillplatform.audit.infrastructure.repository.DownloadLogRepository;import com.company.skillplatform.skill.infrastructure.entity.SkillEntity;import com.company.skillplatform.skill.infrastructure.repository.SkillRepository;import com.company.skillplatform.user.infrastructure.repository.IamUserRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Propagation;import org.springframework.transaction.annotation.Transactional;@Service public class DownloadAuditService{private final DownloadLogRepository logs;private final IamUserRepository users;private final SkillRepository skills;public DownloadAuditService(DownloadLogRepository l,IamUserRepository u,SkillRepository s){logs=l;users=u;skills=s;}@Transactional(propagation=Propagation.REQUIRES_NEW) public void record(Long userId,Long skillId,Long artifactId,Long bundleId,String objectKey){users.findById(userId).ifPresent(u->{SkillEntity skill=skillId==null?null:skills.findById(skillId).orElse(null);logs.save(new DownloadLogEntity(u,skill,artifactId,bundleId,objectKey));});}public void record(Long userId,Long artifactId,Long bundleId,String objectKey){record(userId,null,artifactId,bundleId,objectKey);}public long count(Long skillId){return logs.countBySkillId(skillId);}}
